"""
Tests for Bicep infrastructure files
Validates syntax, linting, and basic structure of Bicep templates
"""

import subprocess
import pytest
from pathlib import Path


@pytest.fixture(autouse=True, scope="module")
def cleanup_bicep_json_artifacts():
    """Remove any .json files generated by Bicep builds after tests complete."""
    yield
    for bicep in BICEP_FILES:
        json_path = bicep.with_suffix('.json')
        if json_path.exists():
            try:
                json_path.unlink()
            except Exception:
                pass

# Get the project root directory
PROJECT_ROOT = Path(__file__).parent.parent.parent
INFRA_DIR = PROJECT_ROOT / "infra"

# Bicep files to test
BICEP_FILES = [
    INFRA_DIR / "main.bicep",
    INFRA_DIR / "ai-foundry.bicep",
    INFRA_DIR / "storage.bicep",
    INFRA_DIR / "container.bicep",
    INFRA_DIR / "keyvault.bicep",
    INFRA_DIR / "communication.bicep",
]


class TestBicepSyntax:
    """Test that all Bicep files have valid syntax"""

    @pytest.mark.parametrize("bicep_file", BICEP_FILES)
    def test_bicep_build(self, bicep_file):
        """Test that bicep files can be built successfully"""
        result = subprocess.run(
            ["az", "bicep", "build", "--file", str(bicep_file)],
            capture_output=True,
            text=True,
        )
        assert result.returncode == 0, f"Bicep build failed for {bicep_file}:\n{result.stderr}"

    @pytest.mark.parametrize("bicep_file", BICEP_FILES)
    def test_bicep_lint(self, bicep_file):
        """Test that bicep files pass linting checks"""
        result = subprocess.run(
            ["az", "bicep", "lint", "--file", str(bicep_file)],
            capture_output=True,
            text=True,
        )
        # Lint returns 0 for success, may have warnings but no errors
        assert result.returncode == 0, f"Bicep lint found errors in {bicep_file}:\n{result.stderr}"


class TestMainBicep:
    """Tests specific to main.bicep"""

    def test_main_has_required_parameters(self):
        """Test that main.bicep has expected parameters"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()
        
        assert "param location" in content, "main.bicep should have location parameter"
        assert "param prefix" in content, "main.bicep should have prefix parameter"

    def test_main_references_modules(self):
        """Test that main.bicep references the required modules"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()
        
        assert "'storage.bicep'" in content, "main.bicep should reference storage.bicep"
        assert "'ai-foundry.bicep'" in content, "main.bicep should reference ai-foundry.bicep"
        assert "'communication.bicep'" in content, "main.bicep should reference communication.bicep"

    def test_main_has_outputs(self):
        """Test that main.bicep has expected outputs"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()
        
        assert "output aiResourceName" in content, "main.bicep should output aiResourceName"
        assert "output storageName" in content, "main.bicep should output storageName"
        assert "output acrLoginServer" in content, "main.bicep should output acrLoginServer"

    def test_main_references_keyvault_module(self):
        """Test that main.bicep wires up the keyvault module"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()

        assert "'keyvault.bicep'" in content, "main.bicep should reference keyvault.bicep"

    def test_main_passes_kv_uri_to_container(self):
        """Test that main.bicep passes the KV URI from kvModule into containerModule"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()

        assert "kvModule.outputs.keyVaultUri" in content, (
            "main.bicep should pass kvModule.outputs.keyVaultUri to containerModule"
        )

    def test_main_managed_identity_defined(self):
        """Test that main.bicep defines the managed identity resource"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()

        assert "Microsoft.ManagedIdentity/userAssignedIdentities" in content, (
            "main.bicep should define the user-assigned managed identity"
        )
        assert "managedIdentity.properties.principalId" in content, (
            "main.bicep should pass managed identity principalId to keyvault module"
        )

    def test_main_passes_acs_to_keyvault(self):
        """Test that main.bicep retrieves the ACS connection string via listKeys() and passes it to keyvault"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()

        assert "listKeys().primaryConnectionString" in content, (
            "main.bicep should call listKeys() on the ACS existing resource reference"
        )
        assert "commModule.outputs.emailDomainName" in content, (
            "main.bicep should pass email domain name to keyvault"
        )

    def test_main_has_communication_outputs(self):
        """Test that main.bicep exposes communication service outputs"""
        bicep_file = INFRA_DIR / "main.bicep"
        content = bicep_file.read_text()

        assert "output communicationServiceName" in content, (
            "main.bicep should output communicationServiceName"
        )
        assert "output emailFromAddress" in content, (
            "main.bicep should output emailFromAddress"
        )


class TestCommunicationBicep:
    """Tests specific to communication.bicep"""

    def test_communication_has_required_parameters(self):
        """Test that communication.bicep has expected parameters"""
        bicep_file = INFRA_DIR / "communication.bicep"
        content = bicep_file.read_text()

        assert "param communicationServiceName" in content, (
            "communication.bicep should have communicationServiceName parameter"
        )
        assert "param emailServiceName" in content, (
            "communication.bicep should have emailServiceName parameter"
        )

    def test_communication_uses_global_location(self):
        """Test that communication resources use global location"""
        bicep_file = INFRA_DIR / "communication.bicep"
        content = bicep_file.read_text()

        # Communication services must be global
        assert "location: 'global'" in content, (
            "communication.bicep should use 'global' location for communication services"
        )

    def test_communication_creates_email_service(self):
        """Test that communication.bicep creates email service"""
        bicep_file = INFRA_DIR / "communication.bicep"
        content = bicep_file.read_text()

        assert "Microsoft.Communication/emailServices@" in content, (
            "communication.bicep should create email service resource"
        )
        assert "dataLocation: 'United States'" in content, (
            "communication.bicep should set data location"
        )

    def test_communication_creates_email_domain(self):
        """Test that communication.bicep creates email domain"""
        bicep_file = INFRA_DIR / "communication.bicep"
        content = bicep_file.read_text()

        assert "Microsoft.Communication/emailServices/domains@" in content, (
            "communication.bicep should create email domain resource"
        )
        assert "domainManagement: 'AzureManaged'" in content, (
            "communication.bicep should use Azure Managed domain"
        )
        assert "userEngagementTracking: 'Disabled'" in content, (
            "communication.bicep should disable user engagement tracking"
        )

    def test_communication_creates_communication_service(self):
        """Test that communication.bicep creates communication service"""
        bicep_file = INFRA_DIR / "communication.bicep"
        content = bicep_file.read_text()

        assert "Microsoft.Communication/communicationServices@" in content, (
            "communication.bicep should create communication service resource"
        )

    def test_communication_outputs_connection_string(self):
        """Test that listKeys() is called in main.bicep, not in communication.bicep outputs
        (Bicep linter forbids secrets in outputs)"""
        main_file = INFRA_DIR / "main.bicep"
        comm_file = INFRA_DIR / "communication.bicep"
        main_content = main_file.read_text()
        comm_content = comm_file.read_text()

        assert "listKeys().primaryConnectionString" in main_content, (
            "main.bicep should call listKeys() on the ACS existing resource"
        )
        assert "listKeys()" not in comm_content, (
            "communication.bicep must not call listKeys() in outputs (linter rule: outputs-should-not-contain-secrets)"
        )

    def test_communication_has_required_outputs(self):
        """Test that communication.bicep exposes required outputs"""
        bicep_file = INFRA_DIR / "communication.bicep"
        content = bicep_file.read_text()

        required_outputs = [
            "output communicationServiceId",
            "output communicationServiceName",
            "output emailServiceId",
            "output emailDomainId",
            "output emailDomainName",
        ]
        for output in required_outputs:
            assert output in content, (
                f"communication.bicep should have {output}"
            )

    def test_main_passes_acs_connection_string_to_keyvault(self):
        """Test that main.bicep calls listKeys() on the ACS resource and passes it to keyvault"""
        main_file = INFRA_DIR / "main.bicep"
        content = main_file.read_text()

        assert "listKeys().primaryConnectionString" in content, (
            "main.bicep should call listKeys() on the ACS resource (not in an output)"
        )
        assert "acsConnectionString:" in content, (
            "main.bicep should pass acsConnectionString to keyvault module"
        )


