class TestBicepIntegration:
    """Integration tests for the complete infrastructure"""

    def test_all_files_exist(self):
        """Test that all expected Bicep files exist"""
        for bicep_file in BICEP_FILES:
            assert bicep_file.exists(), f"Expected Bicep file not found: {bicep_file}"

    def test_no_syntax_errors_in_all_files(self):
        """Test that all Bicep files compile without errors"""
        for bicep_file in BICEP_FILES:
            result = subprocess.run(
                ["az", "bicep", "build", "--file", str(bicep_file), "--stdout"],
                capture_output=True,
                text=True,
            )
            assert result.returncode == 0, f"Compilation failed for {bicep_file}"

    def test_container_references_kv_secrets(self):
        """Test that container.bicep maps all KV secrets to environment variables"""
        bicep_file = INFRA_DIR / "container.bicep"
        content = bicep_file.read_text()

        expected_env_vars = [
            "AZURE_STORAGE_CONNECTION_STRING",
            "AZURE_STORAGE_CONTAINER_NAME",
            "AZURE_AI_PROJECT_API_KEY",
            "AZURE_AI_PROJECT_ENDPOINT",
            "SHAREPOINT_CLIENT_SECRET",
        ]
        for var in expected_env_vars:
            assert var in content, (
                f"container.bicep should map env var '{var}' from a KV secret ref"
            )

    def test_container_uses_user_assigned_identity(self):
        """Test that the Container App Job uses UserAssigned identity for both ACR pull and Key Vault"""
        bicep_file = INFRA_DIR / "container.bicep"
        content = bicep_file.read_text()

        assert "type: 'UserAssigned'" in content, (
            "container.bicep should use UserAssigned identity on the job "
            "for both ACR image pull and Key Vault secret references"
        )
        assert "SystemAssigned" not in content, (
            "container.bicep should not use SystemAssigned identity — "
            "ACR pulls now use the UAMI to avoid RBAC propagation races"
        )
